import{_ as t,c as e,o,a0 as s}from"./chunks/framework.C1J0Vcxi.js";const u=JSON.parse('{"title":"第三十周：K3 RT24 rcpu1 极简固件完整实现与平台重构","description":"","frontmatter":{"title":"第三十周：K3 RT24 rcpu1 极简固件完整实现与平台重构","date":"2026-07-04"},"headers":[],"relativePath":"周报-Oveln/2026-07-04-周报三十.md","filePath":"周报-Oveln/2026-07-04-周报三十.md"}'),r={name:"周报-Oveln/2026-07-04-周报三十.md"};function d(i,a,n,c,l,p){return o(),e("div",null,[...a[0]||(a[0]=[s(`<h1 id="第三十周工作总结" tabindex="-1">第三十周工作总结 <a class="header-anchor" href="#第三十周工作总结" aria-label="Permalink to &quot;第三十周工作总结&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>在完成设计文档与实现计划后，本周实现了 <strong>K3 RT24 rcpu1 极简固件的全部代码</strong>——从 CCU 时钟链、PXA-UART 驱动、pinmux 配置到 <code>Chip</code>/<code>TimerChip</code> trait 实现，以及独立的 K3 app crate 与构建脚本。同时完成了一次重要的 <strong>platform 层重构</strong>：用 <code>Chip::board_init()</code> 替代了对外暴露的 <code>extern &quot;C&quot; _board_init</code> 弱符号模式，使 chip 初始化成为标准 trait 方法。全部改动已通过编译+符号验证，合并入 main 分支。</p><p>20 个文件、+1580/-62 行，产物：<strong><code>k3-minimal</code> bin</strong>——编译出 ELF（entry=<code>0x100804000</code>），经 <code>objcopy</code> 即可生成刷板固件。</p><h2 id="_1-chip-k3-rt24-完整实现" tabindex="-1">1. chip-k3-rt24 完整实现 <a class="header-anchor" href="#_1-chip-k3-rt24-完整实现" aria-label="Permalink to &quot;1. chip-k3-rt24 完整实现&quot;">​</a></h2><h3 id="_1-1-硬件初始化序列-7-步-main-c-已验证" tabindex="-1">1.1 硬件初始化序列（7 步，main.c 已验证） <a class="header-anchor" href="#_1-1-硬件初始化序列-7-步-main-c-已验证" aria-label="Permalink to &quot;1.1 硬件初始化序列（7 步，main.c 已验证）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>步</th><th>操作</th><th>对应文件</th></tr></thead><tbody><tr><td>1</td><td>SPL 握手回写 <code>write32(0xc088007c, 1)</code> (如果不和spl握手，其会忙等一段时间)</td><td><code>clock.rs</code></td></tr><tr><td>2</td><td>上游 ruart_14 DDN gate</td><td><code>clock.rs</code></td></tr><tr><td>3</td><td>UART0 末端 gate + mux 选择</td><td><code>clock.rs</code></td></tr><tr><td>4</td><td>pinmux：GPIO_122/123 → MUX_MODE4</td><td><code>clock.rs</code></td></tr><tr><td>5</td><td>波特率/帧格式（8N1, 115200）</td><td><code>uart.rs</code></td></tr><tr><td>6</td><td>UUE 单元使能（PXA 专属，最易漏）</td><td><code>uart.rs</code></td></tr><tr><td>7</td><td>put_str 轮询 THR</td><td><code>uart.rs</code></td></tr></tbody></table><p>这 7 步在 <code>clock::early_init()</code> + <code>uart::init()</code> 中完成，经 <code>_board_init</code> → <code>Chip::board_init()</code> 链在用户 <code>main</code> 之前执行。</p><p><code>clock.rs</code> 中的寄存器常量（<code>ruart_14</code> gate num/den、<code>uart0</code> mux/div）均与 ESOS 源码 <code>ccu-spacemit-k3.c</code> 逐项交叉验证。</p><h2 id="_2-platform-层重构-chip-board-init" tabindex="-1">2. Platform 层重构：Chip::board_init() <a class="header-anchor" href="#_2-platform-层重构-chip-board-init" aria-label="Permalink to &quot;2. Platform 层重构：Chip::board_init()&quot;">​</a></h2><h3 id="_2-1-问题" tabindex="-1">2.1 问题 <a class="header-anchor" href="#_2-1-问题" aria-label="Permalink to &quot;2.1 问题&quot;">​</a></h3><p>初版设计用 <code>link.x PROVIDE</code> + <code>#[no_mangle] extern &quot;C&quot; fn _board_init()</code> 作为 chip 钩子机制：</p><ul><li>arch crate 提供 <code>_default_board_init</code>（空），link.x <code>PROVIDE(_board_init = _default_board_init)</code></li><li>chip crate 用强 <code>_board_init</code> 覆盖</li></ul><p>这虽然可行，但 <code>_board_init</code> 是一个脱离 trait 体系的裸 extern &quot;C&quot; 函数——调用方（platform）和实现方（chip）之间没有 Rust 类型约束，也没有文档化的接口契约。</p><h3 id="_2-2-方案" tabindex="-1">2.2 方案 <a class="header-anchor" href="#_2-2-方案" aria-label="Permalink to &quot;2.2 方案&quot;">​</a></h3><p>在 <code>Chip</code> trait 中增加 <code>board_init()</code> 方法（带默认空实现），platform 通过 <code>ChipImpl::board_init()</code> 调用。chip crate 在 <code>impl Chip for K3Rt24</code> 中重写该方法即可。</p><p><strong>优势</strong>：</p><ul><li>Rust trait 提供编译期类型检查，实现方不匹配即编译失败</li><li>所有 chip 初始化统一走 <code>Chip</code> trait，新 chip crate 只需 <code>impl Chip</code>，无需理解 link.x 弱符号机制</li><li>调用方代码 <code>ChipImpl::board_init()</code> 自文档化</li></ul><h2 id="_3-独立-k3-app-crate-与构建链" tabindex="-1">3. 独立 K3 app crate 与构建链 <a class="header-anchor" href="#_3-独立-k3-app-crate-与构建链" aria-label="Permalink to &quot;3. 独立 K3 app crate 与构建链&quot;">​</a></h2><h3 id="_3-1-架构隔离" tabindex="-1">3.1 架构隔离 <a class="header-anchor" href="#_3-1-架构隔离" aria-label="Permalink to &quot;3.1 架构隔离&quot;">​</a></h3><p>新建 <code>apps/rt-async-k3</code> crate，与 QEMU <code>apps/rt-async-app</code> 完全隔离：</p><ul><li>各自 memory.x（K3: <code>0x100804000</code>，QEMU: <code>0x80200000</code>）</li><li>各自 target triple（共用 <code>riscv64imac-unknown-none-elf</code>）</li><li>K3 app bin 通过 <code>#[used] static</code> 引用 <code>chip_k3_rt24::K3Rt24</code>，确保 chip rlib 被链接器拉入</li></ul><h3 id="_3-2-xtask-统一命名" tabindex="-1">3.2 xtask 统一命名 <a class="header-anchor" href="#_3-2-xtask-统一命名" aria-label="Permalink to &quot;3.2 xtask 统一命名&quot;">​</a></h3><p><code>xtask build</code> 统一 bin 命名为 <code>&lt;platform&gt;-&lt;bin&gt;</code>（如 <code>qemu-demo</code>、<code>k3-minimal</code>），K3 构建产物为 ELF 而非 bin（objcopy 留给脚本，因需刷板前确认）。</p><h2 id="_4-刷板验证-7-5-完成" tabindex="-1">4. 刷板验证（7/5 完成） <a class="header-anchor" href="#_4-刷板验证-7-5-完成" aria-label="Permalink to &quot;4. 刷板验证（7/5 完成）&quot;">​</a></h2><h3 id="_4-1-真板上成功启动" tabindex="-1">4.1 真板上成功启动 <a class="header-anchor" href="#_4-1-真板上成功启动" aria-label="Permalink to &quot;4.1 真板上成功启动&quot;">​</a></h3><p>周五（7/5）成功将 <code>k3-minimal</code> 固件刷入 K3 实体板，R_UART0 输出启动日志：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I am alive! Hello from rt-async on K3 RT24!</span></span></code></pre></div><blockquote><p><strong>注</strong>：rcpu1 的固件加载由 SPL 通过 <code>rproc_load</code>/<code>rproc_start</code> 完成，<code>esos.itb</code> 中 <code>rcpu1-fw</code> 节点的 load/entry <code>0x1_804000</code> 是 RT24 SRAM 内的硬编码地址，不可改动。</p></blockquote><h2 id="_5-刷写自动化工具链-scripts-flash" tabindex="-1">5 刷写自动化工具链（scripts/flash/） <a class="header-anchor" href="#_5-刷写自动化工具链-scripts-flash" aria-label="Permalink to &quot;5 刷写自动化工具链（scripts/flash/）&quot;">​</a></h2><p>为缩短迭代周期，创建了一套完整的<strong>一键刷写自动化工具链</strong>，覆盖编译→打包→刷写的全流程：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scripts/flash/</span></span>
<span class="line"><span>├── k3-flash.sh                  # 主编排：一键编译+打包+刷写（7 步串联）</span></span>
<span class="line"><span>├── k3-pack-itb.sh               # itb 打包（自包含，不依赖 esos 仓库）</span></span>
<span class="line"><span>├── k3-console.py                # pyserial 串口交互（ensure-uboot / run / fastboot）</span></span>
<span class="line"><span>├── flash.conf                   # 串口配置（编辑一次即可）</span></span>
<span class="line"><span>├── esos_k3_com260_ifx.its       # 精简 ITS 模板（仅 com260_ifx 板型，5 节点）</span></span>
<span class="line"><span>├── payloads/                    # 固定 payload（入库）</span></span>
<span class="line"><span>│   ├── rt24_os0_rcpu.elf        #   rcpu0 esos 固件（固定复用）</span></span>
<span class="line"><span>│   ├── k3_rt240_com260_ifx.dtb  #   rcpu0 设备树</span></span>
<span class="line"><span>│   ├── k3_rt241_com260_ifx.dtb  #   rcpu1 设备树</span></span>
<span class="line"><span>│   └── null.spacemit            #   AP 交互 blob</span></span>
<span class="line"><span>└── README.md</span></span></code></pre></div><p><code>k3-flash.sh</code> 编排以下 7 步：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>▶ build k3-minimal              # cargo xtask build k3-minimal</span></span>
<span class="line"><span>▶ pack esos.itb                 # cp ELF + lzo + mkimage（自包含）</span></span>
<span class="line"><span>▶ ensure board at U-Boot prompt # reset + 抓 autoboot 窗口 → =&gt;</span></span>
<span class="line"><span>▶ enter fastboot                # 板端 fastboot usb 0，主机轮询 devices</span></span>
<span class="line"><span>▶ fastboot stage                # 主机 stage 传输 itb → Ctrl-C 退出 fastboot</span></span>
<span class="line"><span>▶ mtd erase / write             # 写 flash</span></span>
<span class="line"><span>▶ ensure-uboot                  # reset 停在 =&gt;，新固件已就绪</span></span></code></pre></div><p><strong>一键运行</strong>：<code>./scripts/flash/k3-flash.sh</code></p><h2 id="_6-其他改动" tabindex="-1">6 其他改动 <a class="header-anchor" href="#_6-其他改动" aria-label="Permalink to &quot;6 其他改动&quot;">​</a></h2><ul><li><strong>README.md 更新</strong>：修正构建步骤顺序（子模块 → xtask setup → xtask build → rootfs → install → run），补充 Musl 工具链从 <a href="https://github.com/arceos-org/setup-musl/releases/tag/prebuilt" target="_blank" rel="noreferrer">setup-musl</a> 预编译包安装的说明</li><li><strong>rt-async 子模块更新</strong>：同步平台重构（<code>Chip::board_init()</code> 替代弱符号）和相关文档</li></ul><h2 id="_7-本周在-k3-迁移中的位置" tabindex="-1">7. 本周在 K3 迁移中的位置 <a class="header-anchor" href="#_7-本周在-k3-迁移中的位置" aria-label="Permalink to &quot;7. 本周在 K3 迁移中的位置&quot;">​</a></h2><p>对应 <a href="./../项目计划/项目计划-20260528.html">项目计划-20260528</a> K3 适配第一阶段，与上周（二十九周）&quot;下周计划&quot;及本周补充工作对齐：</p><table tabindex="0"><thead><tr><th>上周/本周计划项</th><th>本周状态</th></tr></thead><tbody><tr><td>定位 UART 输入乱码根因</td><td>🟡 疑似硬件问题（CH340），待新硬件到货对照</td></tr><tr><td>实现 PXA-UART <code>Chip::put_str</code> + CCU 时钟使能</td><td>✅ 完成（clock.rs + uart.rs，7 步初始化）</td></tr><tr><td><strong>刷板验证：R_UART0 看到 rt-async 启动日志</strong></td><td>✅ <strong>真板上成功输出！</strong></td></tr><tr><td>刷写自动化工具链</td><td>✅ <code>scripts/flash/</code> 一键刷写</td></tr><tr><td>替代路线调研（软复位/JTAG）</td><td>✅ 两条路线均否决，选自动化 itb+mtd 路线</td></tr></tbody></table><p><strong>里程碑达成</strong>：从代码编译到真板运行的全链路已打通。</p><h2 id="_8-下周计划" tabindex="-1">8. 下周计划 <a class="header-anchor" href="#_8-下周计划" aria-label="Permalink to &quot;8. 下周计划&quot;">​</a></h2><ol><li><strong>替换 StarryOS 为周雨同学版本</strong>：用 <a href="https://github.com/Dirinkbottle/tgoskits/tree/dev" target="_blank" rel="noreferrer">tgoskits</a> 仓库中的 StarryOS 替换当前版本，适配 K3 真板</li><li><strong>AMP 双系统通信调试</strong>： <ul><li>在真板上跑通 StarryOS（X100 大核）与 rt-async（RT24 小核）的共享内存 + IPI 通信</li><li>移植现有 ov-channels / ov-rpc 到真板拓扑</li></ul></li><li><strong>TimerChip 真实现</strong>：研究 rtimer0 寄存器映射，实现 <code>set_alarm</code> / <code>enable_timer_irq</code>，让调度器时钟跑起来</li><li>目标：RT24 上跑通完整的 rt-async 调度循环（定时器中断 → 任务切换）</li></ol>`,43)])])}const b=t(r,[["render",d]]);export{u as __pageData,b as default};
